import pandas as pd,numpy as np,itertools
from sklearn.model_selection import RepeatedKFold
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from catboost import CatBoostRegressor
D=pd.read_csv('b3_htsteel_pareto_train.csv');X=D.iloc[:,:-2];Y=D.iloc[:,-2:].values
ref=np.array([177.,5.]);scale=np.array([1723.,75.])
def hv(q):
 q=(q-ref)/scale;q=q[np.argsort(q[:,0])];a=b=0
 for x,e in q[::-1]:
  if e>b:a+=max(x,0)*(e-b);b=max(b,e)
 return a
def select(p,k=5):
 nd=np.array([not np.any(np.all(p>=p[i],1)&np.any(p>p[i],1)) for i in range(len(p))]);ix=np.where(nd)[0]
 if len(ix)<=k:return ix
 return np.array(max(itertools.combinations(ix,k),key=lambda z:hv(p[list(z)])))
res=[]
rkf=RepeatedKFold(4,3,random_state=938)
for fold,(a,b) in enumerate(rkf.split(X)):
 preds={}
 for leaf in [1,2,4]:
  ps=[]
  for j in range(2):
   m=ExtraTreesRegressor(n_estimators=250,min_samples_leaf=leaf,max_features=1.,random_state=fold);m.fit(X.iloc[a],Y[a,j]);ps.append(m.predict(X.iloc[b]))
  preds[f'et{leaf}']=np.array(ps).T
 for leaf in [1,3]:
  ps=[]
  for j in range(2):
   m=RandomForestRegressor(n_estimators=250,min_samples_leaf=leaf,max_features=.8,random_state=fold);m.fit(X.iloc[a],Y[a,j]);ps.append(m.predict(X.iloc[b]))
  preds[f'rf{leaf}']=np.array(ps).T
 ps=[]
 for j in range(2):
  m=CatBoostRegressor(iterations=500,depth=6,learning_rate=.04,loss_function='RMSE',verbose=False,random_seed=fold);m.fit(X.iloc[a],Y[a,j]);ps.append(m.predict(X.iloc[b]))
 preds['cat']=np.array(ps).T
 m=CatBoostRegressor(iterations=500,depth=6,learning_rate=.04,loss_function='MultiRMSE',verbose=False,random_seed=fold);m.fit(X.iloc[a],Y[a]);preds['catm']=m.predict(X.iloc[b])
 preds['ens']=np.mean([preds[x] for x in ['et1','et2','rf1','cat']],0)
 preds['ens2']=np.mean([preds[x] for x in ['et1','et2','et4','rf1','rf3','cat']],0)
 oracle=hv(Y[b][select(Y[b])])
 for name,p in preds.items():
  z=select(p); res.append((fold,name,hv(Y[b][z]),oracle,','.join(map(str,b[z])),[(round(x),round(e,1)) for x,e in Y[b][z]]))
 print('done',fold)
r=pd.DataFrame(res,columns=['fold','name','hv','oracle','ids','vals']);r.to_pickle('/tmp/hvcv.pkl')
print(r.groupby('name').agg({'hv':['mean','std','median'],'oracle':'mean'}).sort_values(('hv','mean'),ascending=False))
for n in r.groupby('name').hv.mean().nlargest(3).index:print('\n',n);print(r[r.name==n][['fold','hv','oracle','vals']].to_string(index=False))

