import numpy as np
D={'004':(1300,13),'040':(950,20),'074':(850,25),'078':(520,37),'051':(375,50),'018':(280,60)}; ref=np.array([177,5]);s=np.array([1723,75])
def h(keys):
 q=(np.array([D[k] for k in keys])-ref)/s;q=q[np.argsort(q[:,0])];a=b=0
 for x,y in q[::-1]:
  if y>b:a+=x*(y-b);b=y
 return a
base=['004','040','074','078','051'];print(h(base));
for k in base:print('remove',k,h([x for x in base if x!=k]),'loss',h(base)-h([x for x in base if x!=k]))
for k in base:print('replace',k,'018',h([x for x in base if x!=k]+['018']))
